def solve_a(n_target):
    a = [0] * (n_target + 1)
    a[1] = 0
    for n in range(2, n_target + 1):
        max_val = -1
        for i in range(1, n):
            val = a[i] + a[n - i] + min(i, n - i)
            if val > max_val:
                max_val = val
        a[n] = max_val
    return a[n_target]

print(solve_a(2025))

def solve_a_list(n_max):
    a = [0] * (n_max + 1)
    a[1] = 0
    for n in range(2, n_max + 1):
        max_val = -1
        for i in range(1, n):
            val = a[i] + a[n - i] + min(i, n - i)
            if val > max_val:
                max_val = val
        a[n] = max_val
    return a[1:]

print(solve_a_list(20))
